(function(){'use strict';const root=document.querySelector('[data-pdf-subfilter]');if(!root)return;const grid=document.querySelector('[data-pdf-tool-grid]');if(!grid)return;const cards=[...grid.querySelectorAll('[data-pdf-group]')],buttons=[...root.querySelectorAll('[data-pdf-filter]')];function apply(key,btn){buttons.forEach(b=>{const on=b===btn;b.classList.toggle('is-active',on);b.setAttribute('aria-pressed',on?'true':'false')});cards.forEach(c=>{const show=key==='all'||c.dataset.pdfGroup===key;c.hidden=!show;if(show){c.classList.remove('is-filter-reveal');void c.offsetWidth;c.classList.add('is-filter-reveal')}})}buttons.forEach(b=>b.addEventListener('click',()=>apply(b.dataset.pdfFilter,b)));})();
